--- /dev/null
+++ b/records.mjs
@@ -0,0 +1,19 @@
+export function parseRecords(bytes) {
+  // ignoreBOM preserves the BOM as text so the row grammar rejects it.
+  const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes);
+  if (text === '') return [];
