+  ['empty', '', []],
+  ['safe limit', 'max,9007199254740991', [{ id: 'max', amount: Number.MAX_SAFE_INTEGER }]],
+  ['exact IDs', 'A,1\na,2\n__proto__,3\nconstructor,4', [
